1	package relayproof
2	
3	import (
4		"bytes"
5		"encoding/binary"
6		"encoding/json"
7		"fmt"
8		"hash/crc32"
9		"io"
10		"os"
11		"path/filepath"
12		"sort"
13		"strconv"
14	)
15	
16	// On-disk format (queue.log):
17	//
18	//	magic   = "RELAYPROOF-QUEUE-V1\n"
19	//	frame   = uint32-be payload length(N) | N bytes JSON payload | uint32-be CRC32-IEEE(payload)
20	//
21	// The log is an append-only write-ahead log. Every mutating operation is
22	// persisted as one framed, checksummed record and fsynced before it is
23	// acknowledged; a success record frames the local success entry and the nonce
24	// consumption together, so the two can never take effect separately.
25	//
26	// A success (result or compacted state) names the consumed triple in three
27	// independent fields, consumeFrom/consumeTo/consumeNonce, alongside consumeBy.
28	// Chain names are stored verbatim as raw UTF-8 — they may contain ':' or even
29	// U+0000 — so the triple is never flattened into one delimiter-joined string,
30	// which would let distinct routing paths share one consumption identity.
31	//
32	// Crash recovery: a frame missing bytes at end of file, or a final frame with
33	// a bad checksum, is the torn tail of a write that was never acknowledged and
34	// is truncated. Bad checksums or framing anywhere before the end, a foreign
35	// header, or an unsupported version reject the directory with ErrCorrupt;
36	// state is never silently cleared.
37	//
38	// Logs written by older builds recorded the consumption as one NUL-joined
39	// consumeKey string. Such success entries are still accepted on replay: the
40	// key is validated against the record's own (from,to,nonce) and consumeBy,
41	// and only the record's own triple is marked consumed. A legacy key that does
42	// not match the record it is attached to — a genuinely inconsistent old
43	// record — rejects the whole directory with ErrCorrupt instead of silently
44	// accepting or "repairing" the bad entry.
45	
46	const (
47		logName          = "queue.log"
48		logMagic         = "RELAYPROOF-QUEUE-V1\n"
49		compactThreshold = 4 << 20 // compact when the active log grows past 4 MiB
50		compactFileMode  = 0o600
51		frameHeaderSize  = 4
52		frameCRCsSize    = 4
53	)
54	
55	var crcTable = crc32.MakeTable(crc32.IEEE)
56	
57	// JSON log entry kinds.
58	const (
59		kindVersion = "version"
60		kindSource  = "source"
61		kindHeader  = "header"
62		kindSubmit  = "submit"
63		kindResult  = "result"
64		kindState   = "state" // compacted snapshot: full status after >=1 attempts
65		kindAdvance = "advance"
66		currentLogV = 1
67	)
68	
69	type logEntry struct {
70		T string `json:"t"`
71		V int    `json:"v,omitempty"`
72	
73		Chain   string `json:"chain,omitempty"`
74		Height  int64  `json:"height,omitempty"`
75		Root    string `json:"root,omitempty"`
76		Trusted bool   `json:"trusted,omitempty"`
77	
78		Seq       int64  `json:"seq,omitempty"`
79		ID        string `json:"id,omitempty"`
80		From      string `json:"from,omitempty"`
81		To        string `json:"to,omitempty"`
82		Nonce     uint64 `json:"nonce,omitempty"`
83		Payload   string `json:"payload,omitempty"`
84		ProofAt   int64  `json:"proofAt,omitempty"`
85		ExpiresAt int64  `json:"expiresAt,omitempty"`
86	
87		Now       int64  `json:"now,omitempty"`
88		Status    string `json:"status,omitempty"`
89		Reason    string `json:"reason,omitempty"`
90		Attempts  int    `json:"attempts,omitempty"`
91		NextRetry int64  `json:"nextRetry,omitempty"`
92	
93		// Consumed triple of a success entry, stored as three independent values
94		// so routing paths that share a flattened key stay distinct. consumeBy is
95		// the id of the successful message.
96		ConsumeFrom  string `json:"consumeFrom,omitempty"`
97		ConsumeTo    string `json:"consumeTo,omitempty"`
98		ConsumeNonce uint64 `json:"consumeNonce,omitempty"`
99		ConsumeBy    string `json:"consumeBy,omitempty"`
100	
101		// ConsumeKey is the legacy (pre-triple) NUL-joined consumption string. It
102		// is accepted only while replaying logs written by older builds and is
103		// never written anymore.
104		ConsumeKey string `json:"consumeKey,omitempty"`
105	}
106	
107	// legacyNonceKey reproduces the consumption string used by older builds:
108	// from NUL to NUL nonce. It exists solely to validate records in pre-existing
109	// state directories; new state always uses consumeToken triples.
110	func legacyNonceKey(from, to string, nonce uint64) string {
111		return from + "\x00" + to + "\x00" + strconv.FormatUint(nonce, 10)
112	}
113	
114	type store struct {
115		dir  string
116		f    *os.File
117		size int64
118		// snap, when set, supplies a live-state snapshot for log compaction.
119		snap func() *loadedState
120		// injectErr is a test hook forcing append to fail after opening the file.
121		injectErr error
122	}
123	
124	// loadedState is the fully replayed (or live) queue state.
125	type loadedState struct {
126		sources  map[string]bool
127		headers  map[string]*headerState
128		records  map[string]*Record
129		consumed map[consumeToken]string
130		nextSeq  int64
131		now      int64
132	}
133	
134	func openStore(dir string) (*store, *loadedState, error) {
135		path := filepath.Join(dir, logName)
136	
137		if _, err := os.Stat(path); err != nil {
138			if !os.IsNotExist(err) {
139				return nil, nil, fmt.Errorf("stat %s: %w", logName, err)
140			}
141			if err := createLog(path, dir); err != nil {
142				return nil, nil, err
143			}
144		} else if err := checkMagic(path); err != nil {
145			return nil, nil, err
146		}
147	
148		raw, err := os.ReadFile(path)
149		if err != nil {
150			return nil, nil, fmt.Errorf("read %s: %w", logName, err)
151		}
152		goodLen, state, err := replayLog(raw)
153		if err != nil {
154			return nil, nil, err
155		}
156		if int64(len(raw)) != goodLen {
157			// Drop the torn tail of an entry that can never have been acknowledged.
158			tf, err := os.OpenFile(path, os.O_RDWR, compactFileMode)
159			if err != nil {
160				return nil, nil, fmt.Errorf("open %s for repair: %w", logName, err)
161			}
162			if err := tf.Truncate(goodLen); err != nil {
163				tf.Close()
164				return nil, nil, fmt.Errorf("truncate torn log tail: %w", err)
165			}
166			if err := tf.Sync(); err != nil {
167				tf.Close()
168				return nil, nil, fmt.Errorf("sync repaired %s: %w", logName, err)
169			}
170			if err := tf.Close(); err != nil {
171				return nil, nil, err
172			}
173			if err := syncDir(dir); err != nil {
174				return nil, nil, err
175			}
176		}
177	
178		f, err := os.OpenFile(path, os.O_RDWR|os.O_APPEND, compactFileMode)
179		if err != nil {
180			return nil, nil, fmt.Errorf("open %s for append: %w", logName, err)
181		}
182		if _, err := f.Seek(0, io.SeekEnd); err != nil {
183			f.Close()
184			return nil, nil, err
185		}
186		return &store{dir: dir, f: f, size: goodLen}, state, nil
187	}
188	
189	func createLog(path, dir string) error {
190		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, compactFileMode)
191		if err != nil {
192			return fmt.Errorf("create %s: %w", logName, err)
193		}
194		frame := encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))
195		if _, err := f.Write(append([]byte(logMagic), frame...)); err != nil {
196			f.Close()
197			return fmt.Errorf("write %s header: %w", logName, err)
198		}
199		if err := f.Sync(); err != nil {
200			f.Close()
201			return fmt.Errorf("sync %s: %w", logName, err)
202		}
203		if err := f.Close(); err != nil {
204			return err
205		}
206		return syncDir(dir)
207	}
208	
209	func mustMarshal(e *logEntry) []byte {
210		b, err := json.Marshal(e)
211		if err != nil {
212			panic(err)
213		}
214		return b
215	}
216	
217	// encodeFrame wraps a payload with its big-endian length and CRC32.
218	func encodeFrame(payload []byte) []byte {
219		frame := make([]byte, 0, frameHeaderSize+len(payload)+frameCRCsSize)
220		var hdr [4]byte
221		binary.BigEndian.PutUint32(hdr[:], uint32(len(payload)))
222		frame = append(frame, hdr[:]...)
223		frame = append(frame, payload...)
224		var crc [4]byte
225		binary.BigEndian.PutUint32(crc[:], crc32.Checksum(payload, crcTable))
226		frame = append(frame, crc[:]...)
227		return frame
228	}
229	
230	func checkMagic(path string) error {
231		f, err := os.Open(path)
232		if err != nil {
233			return fmt.Errorf("open %s: %w", logName, err)
234		}
235		defer f.Close()
236		buf := make([]byte, len(logMagic))
237		n, err := io.ReadFull(f, buf)
238		if err != nil && err != io.ErrUnexpectedEOF && err != io.EOF {
239			return fmt.Errorf("read %s header: %w", logName, err)
240		}
241		if n < len(logMagic) || !bytes.Equal(buf, []byte(logMagic)) {
242			return fmt.Errorf("%w: missing or foreign %s header", ErrCorrupt, logName)
243		}
244		return nil
245	}
246	
247	// replayLog parses and validates the log, returning the byte length of the
248	// longest intact prefix and the reconstructed state.
249	func replayLog(raw []byte) (int64, *loadedState, error) {
250		if !bytes.HasPrefix(raw, []byte(logMagic)) {
251			return 0, nil, fmt.Errorf("%w: missing %s header", ErrCorrupt, logMagic)
252		}
253		pos := len(logMagic)
254		state := &loadedState{
255			sources:  map[string]bool{},
256			headers:  map[string]*headerState{},
257			records:  map[string]*Record{},
258			consumed: map[consumeToken]string{},
259		}
260	
261		sawVersion := false
262		for pos < len(raw) {
263			// Need at least the length header.
264			if len(raw)-pos < frameHeaderSize {
265				return int64(pos), state, nil // torn length header of an unacked write
266			}
267			n := int(binary.BigEndian.Uint32(raw[pos : pos+frameHeaderSize]))
268			if n == 0 {
269				return 0, nil, fmt.Errorf("%w: zero-length record at offset %d", ErrCorrupt, pos)
270			}
271			bodyStart := pos + frameHeaderSize
272			frameEnd := bodyStart + n + frameCRCsSize
273			if frameEnd > len(raw) {
274				return int64(pos), state, nil // torn body/CRC of an unacked write
275			}
276			payload := raw[bodyStart : bodyStart+n]
277			wantCRC := binary.BigEndian.Uint32(raw[bodyStart+n : frameEnd])
278			if crc32.Checksum(payload, crcTable) != wantCRC {
279				if frameEnd == len(raw) {
280					// Torn sectors of the final, unacknowledged frame.
281					return int64(pos), state, nil
282				}
283				return 0, nil, fmt.Errorf("%w: checksum mismatch at offset %d", ErrCorrupt, pos)
284			}
285			var e logEntry
286			if err := json.Unmarshal(payload, &e); err != nil {
287				return 0, nil, fmt.Errorf("%w: invalid record at offset %d: %v", ErrCorrupt, pos, err)
288			}
289			if !sawVersion {
290				if e.T != kindVersion || e.V != currentLogV {
291					return 0, nil, fmt.Errorf("%w: unsupported log version entry: %+v", ErrCorrupt, e)
292				}
293				sawVersion = true
294			} else if e.T == kindVersion {
295				return 0, nil, fmt.Errorf("%w: unexpected version record at offset %d", ErrCorrupt, pos)
296			} else if err := applyEntry(state, &e); err != nil {
297				return 0, nil, err
298			}
299			pos = frameEnd
300		}
301		if !sawVersion {
302			return 0, nil, fmt.Errorf("%w: missing version record", ErrCorrupt)
303		}
304		return int64(pos), state, nil
305	}
306	
307	// entryCarriesConsumption reports whether a non-success entry smuggles any
308	// consumption field, which is always corrupt.
309	func entryCarriesConsumption(e *logEntry) bool {
310		return e.ConsumeFrom != "" || e.ConsumeTo != "" || e.ConsumeNonce != 0 ||
311			e.ConsumeKey != "" || e.ConsumeBy != ""
312	}
313	
314	// acceptConsumption validates the triple consumed by a success result or
315	// compacted state entry and records it in s.consumed. The triple must
316	// identify the record's own message and be consumed by that message.
317	//
318	// Logs written by older builds carry the consumption as one NUL-joined
319	// consumeKey. Such an entry is accepted only when that legacy key matches the
320	// record's own triple; it is the record's own triple that is marked consumed,
321	// never the ambiguous flattened string — so two distinct paths that happened
322	// to share one old flattened key each consume only themselves. A legacy key
323	// that does not match its record is an inconsistent record and rejected.
324	func acceptConsumption(s *loadedState, rec *Record, e *logEntry, corrupt func(string, ...any) error) (consumeToken, error) {
325		m := rec.Msg.Message
326		if e.ConsumeBy != e.ID {
327			return consumeToken{}, corrupt("success entry for %q is marked consumed by %q", e.ID, e.ConsumeBy)
328		}
329		token := newConsumeToken(m.From, m.To, m.Nonce)
330		hasTriple := e.ConsumeFrom != "" || e.ConsumeTo != "" || e.ConsumeNonce != 0
331		switch {
332		case hasTriple:
333			if e.ConsumeKey != "" {
334				return consumeToken{}, corrupt("success entry for %q carries both a triple and a legacy consume key", e.ID)
335			}
336			if e.ConsumeFrom != m.From || e.ConsumeTo != m.To || e.ConsumeNonce != m.Nonce {
337				return consumeToken{}, corrupt("success entry for %q carries mismatched nonce consumption: %q -> %q nonce %d", e.ID, e.ConsumeFrom, e.ConsumeTo, e.ConsumeNonce)
338			}
339		case e.ConsumeKey != "":
340			if want := legacyNonceKey(m.From, m.To, m.Nonce); e.ConsumeKey != want {
341				return consumeToken{}, corrupt("success entry for %q carries a legacy consume key for a different path", e.ID)
342			}
343		default:
344			return consumeToken{}, corrupt("success entry for %q carries no nonce consumption", e.ID)
345		}
346		if winner, taken := s.consumed[token]; taken {
347			return consumeToken{}, corrupt("nonce %s already consumed by %q while accepting %q", token, winner, e.ID)
348		}
349		s.consumed[token] = e.ID
350		return token, nil
351	}
352	
353	func applyEntry(s *loadedState, e *logEntry) error {
354		corrupt := func(msg string, args ...any) error {
355			return fmt.Errorf("%w: %s", ErrCorrupt, fmt.Sprintf(msg, args...))
356		}
357		switch e.T {
358		case kindSource:
359			if e.Chain == "" {
360				return corrupt("source entry with empty chain")
361			}
362			s.sources[e.Chain] = true
363		case kindHeader:
364			if e.Chain == "" || e.Height < 0 {
365				return corrupt("bad header entry: %+v", e)
366			}
367			// Replay is permissive: historical same-height coverage is never
368			// rejected as a conflict, and recovery relies only on the header
369			// records actually kept in the log. The latest header is the last one
370			// written; the highest trusted header is the max-height trusted one,
371			// with ties going to the later write (matching old overwrite
372			// semantics). Neither is fabricated from lost history.
373			hs := s.headers[e.Chain]
374			if hs == nil {
375				hs = &headerState{}
376				s.headers[e.Chain] = hs
377			}
378			hs.latest = Header{Chain: e.Chain, Height: e.Height, Root: e.Root, Trusted: e.Trusted}
379			if e.Trusted && (hs.trusted == nil || e.Height >= hs.trusted.Height) {
380				t := hs.latest
381				hs.trusted = &t
382			}
383		case kindSubmit:
384			if e.ID == "" || e.From == "" || e.To == "" || e.ProofAt < 0 || e.ExpiresAt < 0 {
385				return corrupt("bad submit entry: %+v", e)
386			}
387			if _, dup := s.records[e.ID]; dup {
388				return corrupt("duplicate submit for id %q", e.ID)
389			}
390			if e.Seq != s.nextSeq {
391				return corrupt("submit seq %d out of order, expected %d", e.Seq, s.nextSeq)
392			}
393			s.records[e.ID] = &Record{
394				Msg: Envelope{
395					Message: Message{
396						ID:      e.ID,
397						From:    e.From,
398						To:      e.To,
399						Nonce:   e.Nonce,
400						Payload: e.Payload,
401						ProofAt: e.ProofAt,
402					},
403					ExpiresAt: e.ExpiresAt,
404				},
405				Status: StatusPending,
406				Reason: "awaiting first processing",
407				Seq:    e.Seq,
408			}
409			s.nextSeq++
410		case kindResult:
411			rec, ok := s.records[e.ID]
412			if !ok {
413				return corrupt("result for unknown id %q", e.ID)
414			}
415			if isTerminal(rec.Status) {
416				return corrupt("result for terminal id %q", e.ID)
417			}
418			if rec.Attempts > 0 && e.Now < rec.LastProcAt {
419				return corrupt("result time %d before prior time %d for %q", e.Now, rec.LastProcAt, e.ID)
420			}
421			if e.Attempts != rec.Attempts+1 {
422				return corrupt("attempts jump %d -> %d for %q", rec.Attempts, e.Attempts, e.ID)
423			}
424			if !validStatus(e.Status) || e.Status == StatusPending {
425				return corrupt("bad result status %q for %q", e.Status, e.ID)
426			}
427			switch e.Status {
428			case StatusWaiting:
429				if e.NextRetry != e.Now+nextRetryDelay(e.Attempts) {
430					return corrupt("waiting result has wrong retry schedule for %q", e.ID)
431				}
432				if entryCarriesConsumption(e) {
433					return corrupt("waiting result for %q carries nonce consumption fields", e.ID)
434				}
435			case StatusSuccess:
436				if e.NextRetry != 0 {
437					return corrupt("success entry for %q carries retry time", e.ID)
438				}
439				if _, err := acceptConsumption(s, rec, e, corrupt); err != nil {
440					return err
441				}
442			default: // terminal failure kinds
443				if e.NextRetry != 0 || entryCarriesConsumption(e) {
444					return corrupt("terminal entry for %q carries scheduling/consume fields", e.ID)
445				}
446			}
447			rec.Attempts = e.Attempts
448			rec.LastProcAt = e.Now
449			rec.Status = e.Status
450			rec.Reason = e.Reason
451			rec.NextRetry = e.NextRetry
452			if e.Now > s.now {
453				s.now = e.Now
454			}
455		case kindState:
456			// Compacted snapshot: the message already has >=1 attempts and the
457			// entry carries its full current status, so there is no attempts-jump
458			// invariant to check against prior result entries (there are none).
459			rec, ok := s.records[e.ID]
460			if !ok {
461				return corrupt("state for unknown id %q", e.ID)
462			}
463			if rec.Attempts != 0 {
464				return corrupt("duplicate state for id %q", e.ID)
465			}
466			if !validStatus(e.Status) || e.Status == StatusPending {
467				return corrupt("bad state status %q for %q", e.Status, e.ID)
468			}
469			if e.Attempts < 1 {
470				return corrupt("state with zero attempts for %q", e.ID)
471			}
472			switch e.Status {
473			case StatusWaiting:
474				if e.NextRetry != e.Now+nextRetryDelay(e.Attempts) {
475					return corrupt("state has wrong retry schedule for %q", e.ID)
476				}
477				if entryCarriesConsumption(e) {
478					return corrupt("waiting state for %q carries nonce consumption fields", e.ID)
479				}
480			case StatusSuccess:
481				if e.NextRetry != 0 {
482					return corrupt("success state for %q carries retry time", e.ID)
483				}
484				if _, err := acceptConsumption(s, rec, e, corrupt); err != nil {
485					return err
486				}
487			default:
488				if e.NextRetry != 0 || entryCarriesConsumption(e) {
489					return corrupt("terminal state for %q carries scheduling/consume fields", e.ID)
490				}
491			}
492			rec.Attempts = e.Attempts
493			rec.LastProcAt = e.Now
494			rec.Status = e.Status
495			rec.Reason = e.Reason
496			rec.NextRetry = e.NextRetry
497			if e.Now > s.now {
498				s.now = e.Now
499			}
500		case kindAdvance:
501			if e.Now < s.now {
502				return corrupt("advance checkpoint %d before known time %d", e.Now, s.now)
503			}
504			s.now = e.Now
505		default:
506			return corrupt("unknown record type %q", e.T)
507		}
508		return nil
509	}
510	
511	func validStatus(s string) bool {
512		switch s {
513		case StatusPending, StatusWaiting, StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
514			return true
515		}
516		return false
517	}
518	
519	func (s *store) close() error {
520		if s.f == nil {
521			return nil
522		}
523		err := s.f.Sync()
524		cerr := s.f.Close()
525		s.f = nil
526		if err != nil {
527			return err
528		}
529		return cerr
530	}
531	
532	// forceClose releases the file without the final sync after a failed write.
533	func (s *store) forceClose() {
534		if s.f == nil {
535			return
536		}
537		s.f.Close()
538		s.f = nil
539	}
540	
541	// append writes one framed, checksummed, fsynced record.
542	func (s *store) append(e *logEntry) error {
543		if s.injectErr != nil {
544			return s.injectErr
545		}
546		body, err := json.Marshal(e)
547		if err != nil {
548			return fmt.Errorf("encode log entry: %w", err)
549		}
550		if _, err := s.f.Write(encodeFrame(body)); err != nil {
551			return fmt.Errorf("write %s: %w", logName, err)
552		}
553		if err := s.f.Sync(); err != nil {
554			return fmt.Errorf("sync %s: %w", logName, err)
555		}
556		if info, err := s.f.Stat(); err == nil {
557			s.size = info.Size()
558		} else {
559			s.size += int64(frameHeaderSize + len(body) + frameCRCsSize)
560		}
561		return nil
562	}
563	
564	// needsCompaction reports whether the log crossed the compaction threshold.
565	func (s *store) needsCompaction() bool {
566		return s.size > compactThreshold && s.snap != nil
567	}
568	
569	func (s *store) appendRegisterSource(chain string) error {
570		return s.append(&logEntry{T: kindSource, Chain: chain})
571	}
572	
573	func (s *store) appendHeader(h Header) error {
574		return s.append(&logEntry{T: kindHeader, Chain: h.Chain, Height: h.Height, Root: h.Root, Trusted: h.Trusted})
575	}
576	
577	func (s *store) appendSubmit(rec *Record) error {
578		m := rec.Msg.Message
579		return s.append(&logEntry{
580			T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
581			Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
582		})
583	}
584	
585	// appendResult records one processing outcome. On success the consumed triple
586	// (consumeFrom/consumeTo/consumeNonce) and its consumer are part of the same
587	// durable record, committing together atomically. token is nil for every
588	// non-success status.
589	func (s *store) appendResult(now int64, rec *Record, status, reason string, attempts int, token *consumeToken, consumeBy string) error {
590		e := &logEntry{
591			T: kindResult, Now: now, ID: rec.Msg.Message.ID,
592			Status: status, Reason: reason, Attempts: attempts,
593		}
594		if status == StatusWaiting {
595			e.NextRetry = now + nextRetryDelay(attempts)
596		}
597		if status == StatusSuccess {
598			if token == nil || consumeBy == "" {
599				return fmt.Errorf("internal error: success result for %q missing nonce consumption", rec.Msg.Message.ID)
600			}
601			e.ConsumeFrom = token.from
602			e.ConsumeTo = token.to
603			e.ConsumeNonce = token.nonce
604			e.ConsumeBy = consumeBy
605		}
606		return s.append(e)
607	}
608	
609	func (s *store) appendAdvance(now int64) error {
610		return s.append(&logEntry{T: kindAdvance, Now: now})
611	}
612	
613	// compact atomically replaces the log with a deterministic snapshot of live
614	// state. It must run while Queue.mu is held (no concurrent mutation), and only
615	// after in-memory state reflects every acknowledged append.
616	func (s *store) compact(state *loadedState) error {
617		entries := []*logEntry{{T: kindVersion, V: currentLogV}}
618	
619		chains := make([]string, 0, len(state.sources))
620		for c := range state.sources {
621			chains = append(chains, c)
622		}
623		sort.Strings(chains)
624		for _, c := range chains {
625			entries = append(entries, &logEntry{T: kindSource, Chain: c})
626		}
627	
628		headerChains := make([]string, 0, len(state.headers))
629		for c := range state.headers {
630			headerChains = append(headerChains, c)
631		}
632		sort.Strings(headerChains)
633		for _, c := range headerChains {
634			hs := state.headers[c]
635			// Write the highest trusted header first, then the latest header when
636			// it differs. Replay reconstructs latest as the last entry and the
637			// highest trusted as the max-height trusted entry, so this order
638			// restores both exactly.
639			if hs.trusted != nil {
640				entries = append(entries, &logEntry{T: kindHeader, Chain: hs.trusted.Chain, Height: hs.trusted.Height, Root: hs.trusted.Root, Trusted: hs.trusted.Trusted})
641			}
642			if hs.trusted == nil || hs.latest != *hs.trusted {
643				entries = append(entries, &logEntry{T: kindHeader, Chain: hs.latest.Chain, Height: hs.latest.Height, Root: hs.latest.Root, Trusted: hs.latest.Trusted})
644			}
645		}
646	
647		seqs := make([]int64, 0, len(state.records))
648		bySeq := make(map[int64]*Record, len(state.records))
649		for _, rec := range state.records {
650			seqs = append(seqs, rec.Seq)
651			bySeq[rec.Seq] = rec
652		}
653		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
654		for _, seq := range seqs {
655			rec := bySeq[seq]
656			m := rec.Msg.Message
657			entries = append(entries, &logEntry{
658				T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
659				Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
660			})
661			if rec.Attempts > 0 {
662				re := &logEntry{
663					T: kindState, Now: rec.LastProcAt, ID: m.ID,
664					Status: rec.Status, Reason: rec.Reason, Attempts: rec.Attempts,
665				}
666				if rec.Status == StatusWaiting {
667					re.NextRetry = rec.NextRetry
668				}
669				if rec.Status == StatusSuccess {
670					re.ConsumeFrom = m.From
671					re.ConsumeTo = m.To
672					re.ConsumeNonce = m.Nonce
673					re.ConsumeBy = m.ID
674				}
675				entries = append(entries, re)
676			}
677		}
678		if state.now > 0 {
679			entries = append(entries, &logEntry{T: kindAdvance, Now: state.now})
680		}
681	
682		tmp := filepath.Join(s.dir, logName+".compact")
683		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, compactFileMode)
684		if err != nil {
685			return err
686		}
687		abort := func(err error) error {
688			f.Close()
689			os.Remove(tmp)
690			return err
691		}
692		if _, err := f.WriteString(logMagic); err != nil {
693			return abort(err)
694		}
695		for _, e := range entries {
696			body, err := json.Marshal(e)
697			if err != nil {
698				return abort(err)
699			}
700			if _, err := f.Write(encodeFrame(body)); err != nil {
701				return abort(err)
702			}
703		}
704		if err := f.Sync(); err != nil {
705			return abort(err)
706		}
707		if err := f.Close(); err != nil {
708			os.Remove(tmp)
709			return err
710		}
711		if err := os.Rename(tmp, filepath.Join(s.dir, logName)); err != nil {
712			os.Remove(tmp)
713			return err
714		}
715		if err := syncDir(s.dir); err != nil {
716			return err
717		}
718		nf, err := os.OpenFile(filepath.Join(s.dir, logName), os.O_RDWR|os.O_APPEND, compactFileMode)
719		if err != nil {
720			return err
721		}
722		if _, err := nf.Seek(0, io.SeekEnd); err != nil {
723			nf.Close()
724			return err
725		}
726		s.f.Close()
727		s.f = nf
728		if info, err := nf.Stat(); err == nil {
729			s.size = info.Size()
730		}
731		return nil
732	}
733	
734	// syncDir fsyncs a directory so that file creation and rename survive a crash.
735	func syncDir(dir string) error {
736		d, err := os.Open(dir)
737		if err != nil {
738			return fmt.Errorf("open directory for sync: %w", err)
739		}
740		defer d.Close()
741		if err := d.Sync(); err != nil {
742			return fmt.Errorf("sync directory %s: %w", dir, err)
743		}
744		return nil
745	}
746

