329	
330		// Jump far beyond several capped intervals: exactly one more attempt.
331		q.Advance(now + 5_000_000)
332		r := statusOf(t, q, "m")
333		if r.Attempts != len(want)+1 {
334			t.Fatalf("jumping intervals must cost one attempt, got %d", r.Attempts)
335		}
336		if r.NextRetry != now+5_000_000+60_000 {
337			t.Fatalf("cap must remain 60s, nextRetry=%d", r.NextRetry)
338		}
339	}
