		t.Fatalf("new queue must report never-advanced time 0")
	}
	r, ok := q.Query("m")
	if !ok || r.Status != StatusPending || r.NextRetry != 0 || r.Attempts != 0 {
		t.Fatalf("unprocessed record: %+v ok=%v", r, ok)
