package relayproof

import (
	"os"
	"path/filepath"
	"testing"
)

func TestZZZDumpHeadBug(t *testing.T) {
	dir := t.TempDir()
	vframe := encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))

	// Case: full length bytes but body/CRC missing (length already saved).
	data := append([]byte(logMagic), vframe[:frameHeaderSize]...)
	path := filepath.Join(dir, logName)
	if err := os.WriteFile(path, data, 0o600); err != nil {
		t.Fatal(err)
	}
	q, err := Open(dir)
	t.Logf("Open err=%v q=%v", err, q != nil)
	if q != nil {
		// Try a mutating op like the user would.
		opErr := q.RegisterSource("a")
		t.Logf("RegisterSource err=%v", opErr)
		q.Close()
	}
	got, _ := os.ReadFile(path)
	t.Logf("log before=%d bytes (% x) after=%d bytes (% x)", len(data), data, len(got), got)
}

